import { nativeEngineVersions } from '../contract/records/engines.js';
import type { RoutingPort } from '../contract/ports/routing.js';
import type {
  RoutingProblem,
  RouteValue,
  Connection,
  Obstacle,
} from '../contract/records/problem.js';
import type { Point } from '../contract/records/geometry.js';
import type { Result } from '../contract/errors.js';
import { failure } from '../contract/errors.js';
/** Narrow runtime ABI corrects stale upstream typings; none of these handles leave the adapter. */
interface Handle {
  delete(): void;
}
interface NativePoint extends Handle {
  readonly x: number;
  readonly y: number;
}
interface NativePath extends Handle {
  size(): number;
  at(index: number): NativePoint;
}
interface NativeConnection {
  setRoutingType(type: unknown): void;
  setRoutingCheckpoints(points: NativeCheckpoints): void;
  displayRoute(): NativePath;
  hasValidRoute(): boolean;
}
interface NativeRouter extends Handle {
  processTransaction(): void;
  setRoutingParameter(parameter: unknown, value: number): void;
}
interface NativeCheckpoints extends Handle {
  push_back(checkpoint: Handle): void;
}
interface NativeApi {
  readonly Router: new (flags: number) => NativeRouter;
  readonly Point: new (x: number, y: number) => NativePoint;
  readonly Rectangle: new (a: NativePoint, b: NativePoint) => Handle;
  readonly ShapeRef: new (router: NativeRouter, rectangle: Handle) => unknown;
  readonly ConnEnd: new (point: NativePoint) => Handle;
  readonly ConnRef: new (router: NativeRouter, source: Handle, target: Handle) => NativeConnection;
  readonly Checkpoint: new (point: NativePoint) => Handle;
  readonly CheckpointVector: new () => NativeCheckpoints;
  readonly RouterFlag: { readonly OrthogonalRouting: { readonly value: number } };
  readonly ConnType: { readonly ConnType_Orthogonal: unknown };
  readonly RoutingParameter: { readonly shapeBufferDistance: unknown };
}
/** Host supplies the pinned, separately served Wasm module; loader failures remain typed at composition. */
export type WasmLoader = () => Promise<unknown>;
const constructors = [
  'Router',
  'Point',
  'Rectangle',
  'ShapeRef',
  'ConnEnd',
  'ConnRef',
  'Checkpoint',
  'CheckpointVector',
];
/** Check the native constructor/enum boundary before calling a version-pinned external ABI. */
function isNative(value: unknown): value is NativeApi {
  if (value === null || typeof value !== 'object') return false;
  return (
    constructors.every((name): boolean => typeof Reflect.get(value, name) === 'function') &&
    hasEnums(value)
  );
}
/** Embind exposes enums as value objects, unlike the obsolete top-level numeric declarations. */
function hasEnums(value: object): boolean {
  const flags: unknown = Reflect.get(value, 'RouterFlag');
  if (!objectLike(flags)) return false;
  return (
    hasRouterFlag(flags) &&
    hasMember(value, 'ConnType', 'ConnType_Orthogonal') &&
    hasMember(value, 'RoutingParameter', 'shapeBufferDistance')
  );
}
/** Required numeric flag is checked separately to keep external-object traversal explicit. */
function hasRouterFlag(flags: object): boolean {
  const flag: unknown = Reflect.get(flags, 'OrthogonalRouting');
  if (flag === null || typeof flag !== 'object') return false;
  return typeof Reflect.get(flag, 'value') === 'number';
}
/** Embind enum namespaces are constructor functions with static members, not plain records. */
function objectLike(value: unknown): value is object {
  return typeof value === 'function' || (value !== null && typeof value === 'object');
}
/** Native enum identity is opaque; only presence is needed to pass it back to its own library. */
function hasMember(value: object, owner: string, key: string): boolean {
  const record: unknown = Reflect.get(value, owner);
  if (!objectLike(record)) return false;
  return Reflect.has(record, key);
}
/** Job-local native allocations are tracked in construction order for reverse cleanup, including failures. */
function own<T extends Handle>(handles: Handle[], handle: T): T {
  handles.push(handle);
  return handle;
}
/** Convert a plain owned coordinate into a temporary native point with explicit lifetime. */
function point(value: Point, native: NativeApi, handles: Handle[]): NativePoint {
  return own(handles, new native.Point(value.x, value.y));
}
/** Router owns registered shapes; only temporary polygon/point handles are explicitly tracked. */
function obstacle(
  item: Obstacle,
  router: NativeRouter,
  native: NativeApi,
  handles: Handle[],
): void {
  const a = point(item.box, native, handles);
  const b = point(
    { x: item.box.x + item.box.width, y: item.box.y + item.box.height },
    native,
    handles,
  );
  const rectangle = own(handles, new native.Rectangle(a, b));
  new native.ShapeRef(router, rectangle);
}
/** Authored routing checkpoints are copied by libavoid; temporary vectors are released with the job. */
function checkpoints(
  points: readonly Point[],
  native: NativeApi,
  handles: Handle[],
): NativeCheckpoints {
  const vector = own(handles, new native.CheckpointVector());
  points.forEach((value): void => {
    const nativePoint = point(value, native, handles);
    const checkpoint = own(handles, new native.Checkpoint(nativePoint));
    vector.push_back(checkpoint);
  });
  return vector;
}
/** Route between explicit approach points; endpoint stubs and independent inspection enforce exact marker direction. */
function connection(
  item: Connection,
  router: NativeRouter,
  native: NativeApi,
  handles: Handle[],
): NativeConnection {
  const source = own(
    handles,
    new native.ConnEnd(point(item.sourceApproach ?? item.source, native, handles)),
  );
  const target = own(
    handles,
    new native.ConnEnd(point(item.targetApproach ?? item.target, native, handles)),
  );
  const connection = new native.ConnRef(router, source, target);
  connection.setRoutingType(native.ConnType.ConnType_Orthogonal);
  connection.setRoutingCheckpoints(checkpoints(item.checkpoints, native, handles));
  return connection;
}
/** Copy each native point before deleting its temporary wrapper; no native memory is returned. */
function readPoint(path: NativePath, index: number): Point {
  const native = path.at(index);
  try {
    return { x: native.x, y: native.y };
  } finally {
    native.delete();
  }
}
/** Invalid native routes fail visibly; their coordinates never escape as partial success. */
function readRoute(item: Connection, connection: NativeConnection): Result<RouteValue> {
  if (!connection.hasValidRoute())
    return failure('candidate-infeasible', item.id, 'Native candidate has no valid route', [
      item.id,
    ]);
  const path = connection.displayRoute();
  try {
    return {
      ok: true,
      value: {
        id: item.id,
        points: endpointStubs(
          item,
          Array.from({ length: path.size() }, (_, index): Point => readPoint(path, index)),
        ),
      },
    };
  } finally {
    path.delete();
  }
}
/** Explicit endpoint stubs enforce marker direction without relying on an unsupported directed ConnEnd ABI. */
function endpointStubs(item: Connection, points: readonly Point[]): readonly Point[] {
  const source = item.sourceApproach === undefined ? [] : [item.source];
  const target = item.targetApproach === undefined ? [] : [item.target];
  return [...source, ...points, ...target];
}
/** All native state is per-call. Router deletion releases its owned shapes/connectors after temporaries. */
function route(problem: RoutingProblem, native: NativeApi): Result<readonly RouteValue[]> {
  const handles: Handle[] = [];
  const router = own(handles, new native.Router(native.RouterFlag.OrthogonalRouting.value));
  try {
    router.setRoutingParameter(native.RoutingParameter.shapeBufferDistance, problem.clearance);
    problem.obstacles.forEach((item): void => obstacle(item, router, native, handles));
    const routes = problem.connections.map(
      (item): { readonly item: Connection; readonly native: NativeConnection } => ({
        item,
        native: connection(item, router, native, handles),
      }),
    );
    router.processTransaction();
    return routes.reduce<Result<readonly RouteValue[]>>(
      (result, item): Result<readonly RouteValue[]> => {
        if (!result.ok) return result;
        return appendRoute(result.value, readRoute(item.item, item.native));
      },
      { ok: true, value: [] },
    );
  } finally {
    disposeAll(handles);
  }
}
/** Preserve candidate infeasibility without exposing an optimistic prefix; Layout owns bounded retry. */
function appendRoute(
  values: readonly RouteValue[],
  next: Result<RouteValue>,
): Result<readonly RouteValue[]> {
  if (!next.ok) return next;
  return { ok: true, value: [...values, next.value] };
}
/** Cleanup attempts every owned allocation even when one native destructor fails. */
function disposeAll(handles: readonly Handle[]): void {
  const disposed = handles.toReversed().map(dispose);
  if (disposed.some((success): boolean => !success))
    throw new Error('Native allocation cleanup failed');
}
/** One destructor failure is recorded without preventing later handles, including the router, from being freed. */
function dispose(handle: Handle): boolean {
  try {
    handle.delete();
    return true;
  } catch {
    return false;
  }
}
/** Native throws become typed failures; Layout retains prior geometry and owns independent route inspection. */
function protectedRoute(problem: RoutingProblem, native: NativeApi): Result<readonly RouteValue[]> {
  try {
    return route(problem, native);
  } catch {
    return failure('engine-failed', 'routing', 'Native obstacle routing failed');
  }
}
/** Load once, allocate router state per job. Host controls module/worker lifetime and restore/retry. */
export async function createRouting(load: WasmLoader): Promise<Result<RoutingPort>> {
  try {
    const native = await load();
    if (!isNative(native))
      return failure('engine-failed', 'routing', 'Pinned routing module ABI is unsupported');
    return {
      ok: true,
      value: {
        version: nativeEngineVersions.routing,
        route: async (problem): Promise<Result<readonly RouteValue[]>> =>
          protectedRoute(problem, native),
      },
    };
  } catch {
    return failure('engine-failed', 'routing', 'Pinned Wasm module could not be loaded');
  }
}

import type { Box, Point } from '../../contract/records/geometry.js';
import type { Connection } from '../../contract/records/problem.js';
import type { RoutePlan } from './native.js';
import { union, pointBounds } from '../geometry/bounds.js';

/** A bounded corridor is only a proposal; native routing and independent checks decide feasibility. */
export interface Corridor {
  readonly connection: Connection;
  readonly index: number;
}
/** Four endpoint-local sides at two measured distances give exactly eight local alternatives. */
export function localCorridors(plan: RoutePlan, gap: number): readonly Corridor[] {
  const bounds = pointBounds([plan.connection.source, plan.connection.target]);
  return [1, 2].flatMap((scale): readonly Corridor[] =>
    around(plan, bounds, gap * scale, (scale - 1) * 4),
  );
}
/** The final fallback alone may depend on whole-scene bounds; it consumes exactly one attempt. */
export function outsideCorridor(plan: RoutePlan, occupied: readonly Box[], gap: number): Corridor {
  const bounds = union(occupied);
  return corridor(
    plan,
    [
      { x: bounds.x - gap - plan.wire.label.width, y: bounds.y - gap - plan.wire.label.height },
      { x: bounds.x + bounds.width + gap, y: bounds.y - gap - plan.wire.label.height },
    ],
    8,
  );
}
/** Measured label dimensions reserve readable space on either side of the endpoint envelope. */
function around(plan: RoutePlan, bounds: Box, gap: number, offset: number): readonly Corridor[] {
  const left = bounds.x - gap - plan.wire.label.width;
  const right = bounds.x + bounds.width + gap + plan.wire.label.width;
  const top = bounds.y - gap - plan.wire.label.height;
  const bottom = bounds.y + bounds.height + gap + plan.wire.label.height;
  return [
    corridor(
      plan,
      [
        { x: bounds.x, y: top },
        { x: bounds.x + bounds.width, y: top },
      ],
      offset,
    ),
    corridor(
      plan,
      [
        { x: bounds.x, y: bottom },
        { x: bounds.x + bounds.width, y: bottom },
      ],
      offset + 1,
    ),
    corridor(
      plan,
      [
        { x: left, y: bounds.y },
        { x: left, y: bounds.y + bounds.height },
      ],
      offset + 2,
    ),
    corridor(
      plan,
      [
        { x: right, y: bounds.y },
        { x: right, y: bounds.y + bounds.height },
      ],
      offset + 3,
    ),
  ];
}
/** Preserve only the approach checkpoints around each alternative, never an old outside detour. */
function corridor(plan: RoutePlan, middle: readonly Point[], index: number): Corridor {
  return {
    index,
    connection: {
      ...plan.connection,
      checkpoints: [
        ...plan.connection.checkpoints.slice(0, 1),
        ...middle,
        ...plan.connection.checkpoints.slice(-1),
      ],
    },
  };
}
/** Manhattan length, bend count and stable proposal index order only independently valid candidates. */
export function compareRoutes(
  a: { readonly points: readonly Point[]; readonly index: number },
  b: { readonly points: readonly Point[]; readonly index: number },
): number {
  const lengthDifference = routeLength(a.points) - routeLength(b.points);
  if (lengthDifference !== 0) return lengthDifference;
  const bendDifference = bends(a.points) - bends(b.points);
  if (bendDifference !== 0) return bendDifference;
  return a.index - b.index;
}
/** Sum actual segment travel, including any reversal produced by the native engine. */
function routeLength(points: readonly Point[]): number {
  return points.slice(1).reduce((total, point, index): number => {
    const previous = points[index];
    if (previous === undefined) return total;
    return total + Math.abs(point.x - previous.x) + Math.abs(point.y - previous.y);
  }, 0);
}
/** Collinear checkpoints do not count as bends; native paths may retain them for direction constraints. */
function bends(points: readonly Point[]): number {
  return points
    .slice(1, -1)
    .filter((point, index): boolean => turns(points[index], point, points[index + 2])).length;
}
/** Missing neighbours cannot contribute a direction change. */
function turns(a: Point | undefined, b: Point, c: Point | undefined): boolean {
  if (a === undefined || c === undefined) return false;
  return (a.x === b.x) !== (b.x === c.x);
}

import type {
  PlacedNode,
  Point,
  ResolvedEndpoint,
  Side,
  Box,
} from '../../contract/records/geometry.js';
import type { VisualWire } from '../../contract/records/input.js';
import { center } from '../geometry/bounds.js';
import { contentBoxes } from './obstacles.js';
import { reject } from '../validation/outcomes.js';
export interface Attachments {
  readonly source: ResolvedEndpoint;
  readonly target: ResolvedEndpoint;
}
/** Resolve the physical visible node; callers never substitute an absent member/object. */
export function visible(id: string, nodes: readonly PlacedNode[]): PlacedNode {
  const found = nodes.find((node): boolean => node.id === id);
  if (!found) return reject('invalid-input', id, 'Wire attachment node is not visible');
  return found;
}
/** Automatic sides follow centre separation, with a stable horizontal tie break. */
function facing(source: PlacedNode, target: PlacedNode): Side {
  const a = center(source.box);
  const b = center(target.box);
  if (Math.abs(b.x - a.x) >= Math.abs(b.y - a.y)) return horizontalSide(a.x, b.x);
  return verticalSide(a.y, b.y);
}
/** Positive horizontal separation exits on the right; ties use the same stable side. */
function horizontalSide(from: number, to: number): Side {
  return to >= from ? 'right' : 'left';
}
/** Positive vertical separation exits below the source. */
function verticalSide(from: number, to: number): Side {
  return to >= from ? 'bottom' : 'top';
}
/** Named sides are hard intent; row members default to a lateral attachment at the measured row. */
function chooseSide(
  requested: VisualWire['route']['sourceSide'],
  member: string | null,
  source: PlacedNode,
  target: PlacedNode,
): Side {
  if (requested !== 'auto') return requested;
  return automaticSide(member, source, target);
}
/** A table/interface member must connect at its row height, not the centre of the object. */
function automaticSide(member: string | null, source: PlacedNode, target: PlacedNode): Side {
  if (member === null) return facing(source, target);
  return center(target.box).x >= center(source.box).x ? 'right' : 'left';
}
/** Orthogonal attachment points lie on the chosen box edge. */
function edge(node: PlacedNode, side: Side): Point {
  const box = node.box;
  const middle = center(box);
  const points = {
    top: { x: middle.x, y: box.y },
    bottom: { x: middle.x, y: box.y + box.height },
    left: { x: box.x, y: middle.y },
    right: { x: box.x + box.width, y: middle.y },
  };
  return points[side];
}
/** Measured member coordinates are node-local and cannot be approximated by row indices. */
function attachment(node: PlacedNode, member: string | null, side: Side): Point {
  if (member === null) return edge(node, side);
  return memberPoint(node, member, side);
}
/** Vertical member-side requests have no row-edge interpretation and are rejected with the member identity. */
function memberPoint(node: PlacedNode, member: string, side: Side): Point {
  if (side === 'top' || side === 'bottom')
    return reject('constraint-conflict', member, 'Member ports require a left or right side', [
      node.id,
      member,
    ]);
  const anchor = node.measured.content.anchors.find((item): boolean => item.member === member);
  if (!anchor)
    return reject('invalid-input', member, 'Measured member anchor is missing', [node.id, member]);
  return { ...edge(node, side), y: node.box.y + anchor.y };
}
/** Resolve both ends before invoking native routing; automatic self-loops leave on different sides. */
export function endpoints(wire: VisualWire, nodes: readonly PlacedNode[]): Attachments {
  const source = visible(wire.source.node, nodes);
  const target = visible(wire.target.node, nodes);
  const sourceSide = chooseSide(wire.route.sourceSide, wire.source.member, source, target);
  const targetSide = selfTarget(wire, source, target);
  return {
    source: {
      ...wire.source,
      side: sourceSide,
      point: attachment(source, wire.source.member, sourceSide),
    },
    target: {
      ...wire.target,
      side: targetSide,
      point: attachment(target, wire.target.member, targetSide),
    },
  };
}
/** A whole-object self-loop's automatic target uses its bottom; explicit sides remain unchanged. */
function selfTarget(wire: VisualWire, source: PlacedNode, target: PlacedNode): Side {
  if (
    wire.source.node === wire.target.node &&
    wire.route.targetSide === 'auto' &&
    wire.target.member === null
  )
    return 'bottom';
  return chooseSide(wire.route.targetSide, wire.target.member, target, source);
}
/** Exact outward points define marker stubs; the native adapter routes their free corridor without a directed ConnEnd constructor. */
export function approach(endpoint: ResolvedEndpoint, distance: number): Point {
  const vectors = {
    top: { x: 0, y: -1 },
    right: { x: 1, y: 0 },
    bottom: { x: 0, y: 1 },
    left: { x: -1, y: 0 },
  };
  const vector = vectors[endpoint.side];
  return { x: endpoint.point.x + vector.x * distance, y: endpoint.point.y + vector.y * distance };
}

/** The first fixed obstacle on the outward ray limits optional routing clearance, never marker length. */
export function departureSpace(endpoint: ResolvedEndpoint, nodes: readonly PlacedNode[]): number {
  const boxes = contentBoxes(nodes.filter((node): boolean => node.id !== endpoint.node));
  return Math.min(Infinity, ...boxes.map((box): number => obstacleDistance(endpoint, box)));
}
/** Normalize every named side to a positive ray; container headers use the same protected content geometry. */
function obstacleDistance(endpoint: ResolvedEndpoint, box: Box): number {
  const point = endpoint.point;
  const rays = {
    right: {
      position: point.x,
      near: box.x,
      far: box.x + box.width,
      across: point.y,
      min: box.y,
      max: box.y + box.height,
    },
    left: {
      position: -point.x,
      near: -box.x - box.width,
      far: -box.x,
      across: point.y,
      min: box.y,
      max: box.y + box.height,
    },
    bottom: {
      position: point.y,
      near: box.y,
      far: box.y + box.height,
      across: point.x,
      min: box.x,
      max: box.x + box.width,
    },
    top: {
      position: -point.y,
      near: -box.y - box.height,
      far: -box.y,
      across: point.x,
      min: box.x,
      max: box.x + box.width,
    },
  };
  return distanceAlongRay(rays[endpoint.side]);
}
/** Obstacles behind the endpoint or outside its attachment axis do not constrain departure. */
function distanceAlongRay(ray: {
  readonly position: number;
  readonly near: number;
  readonly far: number;
  readonly across: number;
  readonly min: number;
  readonly max: number;
}): number {
  if (ray.across <= ray.min || ray.across >= ray.max || ray.far <= ray.position) return Infinity;
  return Math.max(0, ray.near - ray.position);
}

import type { VisualWire } from '../../contract/records/input.js';
import type { PlacedNode, Point, Box } from '../../contract/records/geometry.js';
import { point } from '../../contract/records/geometry.js';
import type { Connection, RouteValue, Obstacle } from '../../contract/records/problem.js';
import type { SupplementalMeasurements } from '../../contract/types.js';
import type { RoutingContext } from '../../contract/types.js';
import type { Result } from '../../contract/errors.js';
import type { Attachments } from './endpoints.js';
import { approach, endpoints, visible, departureSpace } from './endpoints.js';
import { validRoute } from './checks.js';
import { union } from '../geometry/bounds.js';
import { samePoint } from '../geometry/intersections.js';
import { reject, requireValue } from '../validation/outcomes.js';
export interface RoutePlan {
  readonly wire: VisualWire;
  readonly attachments: Attachments;
  readonly connection: Connection;
  readonly manual: readonly Point[] | null;
  readonly clearance: number;
}
/** Parallel connections get separate approach lengths without altering the actual row/side attachment. */
export function plan(
  wire: VisualWire,
  nodes: readonly PlacedNode[],
  metrics: SupplementalMeasurements,
  context: RoutingContext,
  parallel: number,
): RoutePlan {
  const resolved = endpoints(wire, nodes);
  const clearance = context.options.routeClearance * 2;
  const sourceSpace = departureSpace(resolved.source, nodes);
  const targetSpace = departureSpace(resolved.target, nodes);
  const sourceDistance = departureDistance(
    wire.id,
    metrics.markers[wire.sourceMarker].advance,
    clearance,
    sourceSpace,
  );
  const targetDistance = departureDistance(
    wire.id,
    metrics.markers[wire.targetMarker].advance,
    clearance,
    targetSpace,
  );
  const source = approach(resolved.source, sourceDistance);
  const target = approach(resolved.target, targetDistance);
  return {
    wire,
    attachments: resolved,
    manual: wire.route.manual ?? null,
    clearance: Math.min(
      context.options.routeClearance,
      sourceSpace - sourceDistance,
      targetSpace - targetDistance,
    ),
    connection: {
      id: wire.id,
      source: resolved.source.point,
      target: resolved.target.point,
      sourceSide: resolved.source.side,
      targetSide: resolved.target.side,
      sourceApproach: source,
      targetApproach: target,
      checkpoints: parallelCheckpoints(
        source,
        target,
        resolved.source.side,
        [visible(wire.source.node, nodes), visible(wire.target.node, nodes)],
        parallel,
        clearance,
        wire.label.height,
      ),
    },
  };
}
/** Fixed content may reduce optional clearance; a marker that cannot physically fit is a named placement constraint. */
function departureDistance(id: string, advance: number, preferred: number, space: number): number {
  if (advance > space)
    return reject(
      'constraint-conflict',
      id,
      'Required endpoint marker approach is blocked by fixed content',
      [id],
    );
  return Math.max(advance, Math.min(preferred + advance, space / 2));
}
/** Parallel wires reserve distinct outside lanes while keeping the same exact semantic endpoints. */
function parallelCheckpoints(
  source: Point,
  target: Point,
  side: Connection['sourceSide'],
  nodes: readonly PlacedNode[],
  parallel: number,
  gap: number,
  labelHeight: number,
): readonly Point[] {
  if (parallel === 0) return [source, target];
  const bounds = union(nodes.map((node): Box => node.box));
  const distance = (parallel + 1) * (gap + labelHeight);
  return laneCheckpoints(source, target, side, bounds.x - distance, bounds.y - distance);
}
/** Outside checkpoint pairs create a visible lane along the endpoint's perpendicular axis. */
function laneCheckpoints(
  source: Point,
  target: Point,
  side: Connection['sourceSide'],
  x: number,
  y: number,
): readonly Point[] {
  if (side === 'left' || side === 'right')
    return [source, { x: source.x, y }, { x: target.x, y }, target];
  return [source, { x, y: source.y }, { x, y: target.y }, target];
}
/** Locked authored routes are accepted only if every original point remains valid. */
export function manual(
  plan: RoutePlan,
  obstacles: readonly Obstacle[],
  metrics: SupplementalMeasurements,
): RouteValue | null {
  if (plan.manual === null) return null;
  const valid = validRoute(
    plan.manual,
    plan.attachments.source,
    plan.attachments.target,
    obstacles.map((item): Box => item.box),
    plan.wire,
    metrics,
  );
  if (valid) return { id: plan.wire.id, points: plan.manual };
  return invalidManual(plan);
}
/** Soft invalid geometry requests native rerouting; a hard lock instead produces a named conflict. */
function invalidManual(plan: RoutePlan): RouteValue | null {
  if (plan.wire.route.locked)
    return reject(
      'constraint-conflict',
      plan.wire.id,
      'Locked manual route no longer matches ports or clear content',
      [plan.wire.id],
    );
  return null;
}
/** Remove only consecutive duplicate points from native output; authored manual vertices are untouched. */
function checkedRoute(value: RouteValue): RouteValue {
  value.points.forEach(checkPoint);
  return {
    ...value,
    points: value.points.filter((item, index): boolean => distinct(item, value.points[index - 1])),
  };
}
/** A missing predecessor identifies the first native point. */
function distinct(point: Point, previous: Point | undefined): boolean {
  if (previous === undefined) return true;
  return !samePoint(point, previous);
}
/** Native nonfinite/oversized coordinates cannot reach path generation. */
function checkPoint(value: Point): void {
  if (!point.safeParse(value).success)
