  const a = node(scene, 'a').box;
  const b = node(scene, 'b').box;
  const policies = {
    right: {
      main: b.x - a.x - a.width,
      cross: b.y - a.y,
      mainEqual: a.x - b.x,
      crossOrder: b.y - a.y - a.height,
    },
    left: {
      main: a.x - b.x - b.width,
      cross: b.y - a.y,
